<?php
require __DIR__.'/includes/functions.php'; $p=product((int)get('id')); if(!$p) { http_response_code(404); $title='Product not found'; require ROOT.'/includes/header.php'; echo '<div class="empty-state"><h1>Product not found</h1><a href="'.url('shop.php').'">Explore the collection</a></div>'; require ROOT.'/includes/footer.php'; exit; }
$title=$p['name']; $images=all('SELECT * FROM product_images WHERE product_id=? ORDER BY id',[$p['id']]); $reviews=all('SELECT r.*,u.full_name FROM reviews r JOIN users u ON u.id=r.user_id WHERE product_id=? ORDER BY r.created_at DESC',[$p['id']]); require ROOT.'/includes/header.php'; ?>
<div class="breadcrumbs"><a href="<?= url('shop.php') ?>">Shop</a> / <?= e($p['category_name']) ?> / <?= e($p['name']) ?></div><div class="product-detail"><section><div class="gallery-main"><img id="main-product-image" src="<?= image_url($p['image']) ?>" alt="<?= e($p['name']) ?>" width="500" height="420"></div><div class="gallery-thumbs"><?php foreach($images as $im): ?><button data-gallery="<?= image_url($im['image']) ?>" aria-label="View alternate image of <?= e($p['name']) ?>"><img src="<?= image_url($im['image']) ?>" alt="" width="100" height="84"></button><?php endforeach; ?></div></section><section class="product-description"><p class="eyebrow"><?= e($p['category_name']) ?> / NEXORA EDIT</p><h1><?= e($p['name']) ?></h1><p class="stars">★ <?= $p['rating']>0?number_format((float)$p['rating'],1):'Not rated yet' ?> <a href="#reviews">(<?= count($reviews) ?> reviews)</a></p><div class="detail-price"><?= money(price($p)) ?> <?php if($p['sale_price']!==null): ?><del><?= money($p['price']) ?></del><span class="pill">Save <?= money((float)$p['price']-price($p)) ?></span><?php endif; ?></div><p><?= nl2br(e($p['description'])) ?></p><p class="stock"><?= $p['stock']>0?e($p['stock']).' available':'Out of stock' ?></p><form action="<?= url('action.php') ?>" method="post" data-ajax><?= csrf() ?><input type="hidden" name="id" value="<?= $p['id'] ?>"><?php foreach(['sizes'=>'Size','colors'=>'Color'] as $key=>$label): if(options($p[$key])): ?><label><?= $label ?><select class="form-select" name="<?= $key==='sizes'?'size':'color' ?>"><?php foreach(options($p[$key]) as $opt): ?><option><?= e($opt) ?></option><?php endforeach; ?></select></label><?php endif; endforeach; ?><label>Quantity<input name="quantity" type="number" min="1" max="<?= max(1,min(99,(int)$p['stock'])) ?>" value="1" class="form-control quantity-input" required></label><div class="d-flex gap-2 mt-3"><button class="btn btn-soft flex-fill" name="action" value="add" <?= !$p['stock']?'disabled':'' ?>>Add to cart</button><button class="btn btn-accent flex-fill" name="action" value="buy" <?= !$p['stock']?'disabled':'' ?>>Buy now ↗</button></div></form><form action="<?= url('action.php') ?>" method="post" data-ajax class="mt-3"><?= csrf() ?><input type="hidden" name="id" value="<?= $p['id'] ?>"><button class="btn btn-link" name="action" value="wishlist"><i class="fa-regular fa-heart"></i> Save to wishlist</button></form><div class="secure-note"><i class="fa-solid fa-truck-fast"></i> Free delivery from ₱3,000 · Cash on delivery available</div></section></div>
<section id="reviews" class="section-space"><div class="section-heading"><h2>Real thoughts. <span class="gradient-text">Your perspective.</span></h2><span><?= count($reviews) ?> reviews</span></div><div class="row g-4"><div class="col-lg-7"><?php if(!$reviews): ?><p>No reviews yet. Be the first to share your thoughts.</p><?php endif; foreach($reviews as $r): ?><article class="glass review"><strong><?= e($r['full_name']) ?></strong><span class="stars"><?= str_repeat('★',(int)$r['rating']) ?></span><p><?= nl2br(e($r['comment'])) ?></p><small><?= e(date('M j, Y',strtotime($r['created_at']))) ?></small></article><?php endforeach; ?></div><div class="col-lg-5 glass p-4"><?php if(user()): ?><h3>Your review</h3><form action="<?= url('action.php') ?>" method="post"><?= csrf() ?><input type="hidden" name="id" value="<?= $p['id'] ?>"><label>Rating<select name="rating" class="form-select"><?php for($i=5;$i>=1;$i--): ?><option value="<?= $i ?>"><?= $i ?> stars</option><?php endfor; ?></select></label><label>Your thoughts<textarea name="comment" minlength="5" maxlength="2000" rows="3" class="form-control" required></textarea></label><button class="btn btn-accent" name="action" value="review">Save review</button></form><?php else: ?><h3>Share your perspective</h3><a href="<?= url('login.php') ?>">Sign in to leave a review ↗</a><?php endif; ?></div></div></section>
<section class="section-space"><div class="section-heading"><h2>Keep exploring.</h2></div><div class="product-grid"><?php $related=all('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.active=1 AND p.id<>? ORDER BY (p.category_id=?) DESC,p.id LIMIT 4',[$p['id'],$p['category_id']]); foreach($related as $p) require ROOT.'/includes/product-card.php'; ?></div></section><?php require ROOT.'/includes/footer.php'; ?>
